import * as THREE from 'three';
// Visual reference dimensions only. No surveyed track or interlocking plan is implied.
let ballast99;
function ballastMap99(){if(ballast99)return ballast99;const c=globalThis.document?.createElement?.('canvas');const ctx=c?.getContext?.('2d');if(!ctx?.createImageData)return null;c.width=c.height=128;const im=ctx.createImageData(128,128);let seed=99;for(let i=0;i<im.data.length;i+=4){seed=(1664525*seed+1013904223)>>>0;const g=62+(seed%67);im.data.set([g+7,g+6,g+2,255],i);}ctx.putImageData(im,0,0);ballast99=new THREE.CanvasTexture(c);ballast99.wrapS=ballast99.wrapT=THREE.RepeatWrapping;ballast99.colorSpace=THREE.SRGBColorSpace;return ballast99;}
export function buildTrack99(view,line){view.trackChunks99=[];const map=ballastMap99(),dummy=new THREE.Object3D();
 for(let a=-250;a<line.total+250;a+=200){const b=Math.min(a+200,line.total+250),length=b-a,group=new THREE.Group();group.name='Via_neumatica99';group.userData={track99:true,from:a,to:b};view.infrastructure.add(group);view.trackChunks99.push(group);const n=Math.ceil(length/.9),ties=new THREE.InstancedMesh(new THREE.BoxGeometry(.22,.12,2.93),view.mat('#7f8079',{name:'Concreto durmientes',roughness:.95}),n*2),fixings=new THREE.InstancedMesh(new THREE.BoxGeometry(.19,.055,.19),view.mat('#403c31',{name:'Fundicion fijaciones',metalness:.55,roughness:.67}),n*8);ties.name='Durmientes99';fixings.name='Fijaciones99';let ti=0,fi=0;
 for(const z of[-1.8,1.8]){
  const base=view.box(group,(a+b)/2,.015,z,length,.13,2.99,'#807a6c',{roughness:1});base.name='Balasto99';if(map){base.material.map=map;base.material.bumpMap=map;base.material.bumpScale=.035;const uv=base.geometry.attributes.uv;if(!base.geometry.userData.ballastUV99){for(let i=0;i<uv.count;i++)uv.setXY(i,uv.getX(i)*length/.7,uv.getY(i)*4);base.geometry.userData.ballastUV99=true;}}
  for(const side of[-1,1]){
   const rail=view.box(group,(a+b)/2,.245,z+side*.72,length,.125,.075,'#a2a6a3',{name:'Acero riel',metalness:.88,roughness:.28});rail.name='Riel_seguridad99';
   const web=view.box(group,(a+b)/2,.17,z+side*.72,length,.09,.036,'#62594a',{name:'Acero alma riel',metalness:.65});web.name='Alma_riel99';
   const runway=view.box(group,(a+b)/2,.265,z+side*1.04,length,.145,.255,'#8d918c',{name:'Acero pista rodamiento',metalness:.72,roughness:.38});runway.name='Pista_rodamiento99';
   const guide=view.box(group,(a+b)/2,.405,z+side*1.39,length,.20,.07,'#8c8f89',{name:'Acero barra guia',metalness:.82,roughness:.33});guide.name='Barra_guia99';
  }
  for(let j=0;j<n;j++){const x=a+(j+.5)*length/n;dummy.position.set(x,.105,z);dummy.updateMatrix();ties.setMatrixAt(ti++,dummy.matrix);for(const dz of[-1.39,-.72,.72,1.39]){dummy.position.set(x,.19,z+dz);dummy.updateMatrix();fixings.setMatrixAt(fi++,dummy.matrix);}}
 }
 ties.count=ti;fixings.count=fi;group.add(ties,fixings);
 }
}
export function retireStationTracks99(scene){const pattern=/^(Barra gu[ií]a|Base de v[ií]a|Lecho de v[ií]a|Pista de rodamiento|Riel de respaldo|Riel de seguridad|Durmiente)([. _0-9]|$)/i;const old=[];scene.traverse(o=>{if(o.isMesh&&pattern.test(o.name.replaceAll('_',' ')))old.push(o);});for(const o of old){o.removeFromParent();o.geometry?.dispose();}return old.length;}
export function buildStationSafety99(view,line){view.stationSafety99=[];view.signals99=[];const labels=new Map();const label=(parent,text,...args)=>{const key=JSON.stringify([text,...args.slice(3)]);if(!labels.has(key)){const mesh=view.textPanel(parent,text,...args);mesh.userData.safetyLabel99=true;labels.set(key,mesh);return mesh;}const mesh=labels.get(key).clone();mesh.position.set(...args.slice(0,3));parent.add(mesh);return mesh;};
 for(let i=0;i<line.stations.length;i++){const center=line.distances[i],root=new THREE.Group();root.userData={stationSafety99:true,from:center-100,to:center+100};view.infrastructure.add(root);view.stationSafety99.push(root);
  for(const end of[-1,1])for(const side of[-1,1]){const sign=new THREE.Group();sign.name='PELIGRO_NO_PASE99';sign.position.set(center+end*77,0,side*4.0);sign.rotation.y=-end*Math.PI/2;root.add(sign);view.box(sign,0,1.09,0,.58,.80,.055,'#d8b333');view.box(sign,0,.56,.02,.045,1.1,.055,'#525649');label(sign,'PELIGRO',0,1.38,.032,.52,.14,'#d8b333','#171a16');label(sign,'NO PASE',0,.82,.032,.53,.16,'#d8b333','#171a16');const ring=new THREE.Mesh(new THREE.TorusGeometry(.17,.025,8,24),view.mat('#b82224'));ring.position.set(0,1.1,.042);sign.add(ring);const slash=view.box(sign,0,1.1,.043,.40,.04,.025,'#b82224');slash.rotation.z=-Math.PI/4;}
  for(const direction of[-1,1]){const signal=new THREE.Group();signal.name='Semaforo_salida99';const s=center+direction*88,z=-direction*3.9;signal.position.set(s,0,z);signal.rotation.y=-direction*Math.PI/2;signal.userData={signal99:true,stationIndex:i,direction,s,aspect:'red'};root.add(signal);view.box(signal,0,.87,0,.07,1.75,.07,'#767c72');view.box(signal,0,2.1,0,.34,.94,.18,'#161d1c');const lamps={};for(const [name,y,color]of[['green',2.38,'#2ccf82'],['amber',2.1,'#e1b73d'],['red',1.82,'#ff3c31']]){const material=new THREE.MeshStandardMaterial({color:'#26302b',emissive:color,emissiveIntensity:0,roughness:.32});const lens=new THREE.Mesh(new THREE.CylinderGeometry(.105,.105,.04,16),material);lens.userData.signalLamp99=true;lens.rotation.x=Math.PI/2;lens.position.set(0,y,.12);signal.add(lens);lamps[name]=lens;view.box(signal,0,y+.11,.19,.29,.035,.24,'#161d1c');}label(signal,'S'+(i+1),0,1.43,.105,.34,.18,'#cbb044','#111b16');view.signals99.push({group:signal,lamps,line:line.stations[0].linea,index:i,direction,s,aspect:null});}
 }
}
export function updateSignals99(view,engine,anchor){for(const root of view.stationSafety99||[])root.visible=root.userData.to>anchor-900&&root.userData.from<anchor+900;for(const chunk of view.trackChunks99||[])chunk.visible=chunk.userData.to>anchor-900&&chunk.userData.from<anchor+900;
 for(const signal of view.signals99||[]){if(!signal.group.parent.visible)continue;const line=engine.lines[signal.line],next=signal.index+signal.direction;const occupied=engine.trains.some(t=>t.line===signal.line&&t.direction===signal.direction&&(t.position-signal.s)*signal.direction>-80&&(t.position-signal.s)*signal.direction<(Math.abs((line.distances[next]??signal.s+signal.direction*100)-signal.s)+80));const aspect=engine.emergency||engine.power?.[signal.line]===false||next<0||next>=line.stations.length||occupied?'red':'green';if(aspect===signal.aspect)continue;signal.aspect=aspect;signal.group.userData.aspect=aspect;for(const[name,lens]of Object.entries(signal.lamps)){lens.material.color.set(name===aspect?lens.material.emissive:0x26302b);lens.material.emissiveIntensity=name===aspect?1.7:0;}}
}
